def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics

    h = max(0, int(horizon))
    if h == 0:
        return []

    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h

    label = str(frequency).lower()
    p = 24 if 'hour' in label else (7 if 'day' in label else 1)
    nonnegative = min(y) >= 0.0

    def phase_median(train, n, window):
        result = []
        for step in range(n):
            phase = (len(train) + step) % p
            values = [train[i] for i in range(phase, len(train), p)]
            values = values[-window:]
            result.append(float(statistics.median(values)) if values else float(train[-1]))
        return result

    def analog_predict(train, n, context, neighbors, blend):
        baseline = phase_median(train, n, 3)
        if len(train) < context + n + p:
            return baseline
        target_context = train[-context:]
        center = statistics.median(target_context)
        scale = statistics.median([abs(v - center) for v in target_context])
        if scale < 1e-9:
            scale = max(0.1, abs(center), 1e-9)
        origins = []
        latest_origin = len(train) - n
        for origin in range(context, latest_origin + 1):
            if origin % p != len(train) % p:
                continue
            candidate = train[origin - context:origin]
            distance = sum(abs(a - b) for a, b in zip(target_context, candidate)) / (context * scale)
            age_cycles = (len(train) - origin) / float(p)
            distance += 0.01 * age_cycles
            origins.append((distance, origin))
        if not origins:
            return baseline
        origins.sort(key=lambda item: item[0])
        chosen = origins[:min(neighbors, len(origins))]
        weights = [1.0 / (0.05 + item[0]) for item in chosen]
        total_weight = sum(weights)
        result = []
        for step in range(n):
            analog = sum(weight * train[origin + step] for weight, (_, origin) in zip(weights, chosen)) / total_weight
            value = blend * analog + (1.0 - blend) * baseline[step]
            if nonnegative:
                value = max(0.0, value)
            result.append(float(value))
        return result

    def smape(actual, predicted):
        errors = []
        for a, q in zip(actual, predicted):
            denominator = abs(a) + abs(q)
            if denominator > 1e-12:
                errors.append(200.0 * abs(a - q) / denominator)
        return sum(errors) / len(errors) if errors else 0.0

    candidates = [('seasonal', window, 0, 0.0) for window in (1, 2, 3, 5)]
    candidates += [('analog', context, neighbors, blend)
                   for context in (6, 12, 24)
                   for neighbors in (1, 2, 3)
                   for blend in (0.5, 0.75, 1.0)]

    folds = []
    for back in (3, 2, 1):
        cut = len(y) - back * p
        if cut >= 4 * p:
            folds.append((y[:cut], y[cut:cut + p]))

    if not folds:
        return phase_median(y, h, min(3, max(1, len(y) // p)))

    best_candidate = None
    best_objective = float('inf')
    for candidate in candidates:
        errors = []
        for train, actual in folds:
            if candidate[0] == 'seasonal':
                predicted = phase_median(train, len(actual), candidate[1])
            else:
                predicted = analog_predict(train, len(actual), candidate[1], candidate[2], candidate[3])
            errors.append(smape(actual, predicted))
        objective = 0.7 * statistics.median(errors) + 0.3 * max(errors)
        if objective < best_objective:
            best_objective = objective
            best_candidate = candidate

    if best_candidate[0] == 'seasonal':
        result = phase_median(y, h, best_candidate[1])
    else:
        result = analog_predict(y, h, best_candidate[1], best_candidate[2], best_candidate[3])
    if nonnegative:
        result = [max(0.0, float(value)) for value in result]
    return result
